# Extract keys except commonsense
keys = [k for k in data if k != 'commonsense']

# Compute mean and min/max for variance
avg_values = [np.mean(data[k]['accuracy']) for k in keys]
min_values = [np.min(data[k]['accuracy']) for k in keys]
max_values = [np.max(data[k]['accuracy']) for k in keys]

# Compute commonsense average
commonsense_avg = np.mean(data['commonsense']['accuracy'])

# Radar chart setup
num_vars = len(keys)
angles = np.linspace(0, 2*np.pi, num_vars, endpoint=False).tolist()
angles += angles[:1]  # close loop

# Close the values
avg_values += avg_values[:1]
min_values += min_values[:1]
max_values += max_values[:1]

# Radial limits
radial_min = 20
radial_max = commonsense_avg + 5

# Create figure
fig, ax = plt.subplots(figsize=(8,8), subplot_kw=dict(polar=True))

# Plot variance as gray shaded area
ax.fill_between(angles, min_values, max_values, color='gray', alpha=0.2, zorder=1)

# Plot average line with markers
ax.plot(angles, avg_values, color='gray', linewidth=2, marker='o', zorder=2)

# Draw dashed circle for commonsense
theta = np.linspace(0, 2*np.pi, 200)
r = np.full_like(theta, commonsense_avg)
ax.plot(theta, r, linestyle='--', color=data['commonsense']['color'], linewidth=2, zorder=3)

# Split labels on spaces for line breaks
for i, angle in enumerate(angles[:-1]):
    label = "\n".join(data[keys[i]]['label'].split(" "))
    ax.text(
        angle,
        radial_max + 1,
        label,
        color='black',
        fontsize=14,
        fontweight='bold',
        ha='center',
        va='center'
    )

# Radial limits
ax.set_ylim(radial_min, radial_max)

# Gray percentage rings
for perc in [20,30,40,50,60]:
    ax.plot(np.linspace(0, 2*np.pi, 200), np.full(200, perc), color='gray', linestyle=':', linewidth=0.7)
    ax.text(np.pi/2, perc, f"{perc}%", color='gray', fontsize=10, ha='center', va='bottom')

# Remove ticks
ax.set_xticks([])
ax.set_yticklabels([])

# Save tightly cropped
plt.savefig("star_plot_avg_variance.png", bbox_inches='tight', pad_inches=0, dpi=300)
plt.close()